class Thesis(SimpleDocTemplate):
    def afterFlowable(self, f):
        if isinstance(f,Paragraph):
            name=f.style.name
            if name in ('ChapterX','SectionX'):
                self.notify('TOCEntry',(0 if name=='ChapterX' else 1,f.getPlainText().replace('1Introduction','1: Introduction').replace('2Literature','2: Literature').replace('3Preliminaries','3: Preliminaries').replace('4Proposed','4: Proposed').replace('5Experiments','5: Experiments').replace('6Results','6: Results').replace('7Conclusion','7: Conclusion'),self.page))
            if name=='CaptionX' and f.getPlainText().startswith('Figure '): self.notify('FigureEntry',(0,f.getPlainText().replace('1Introduction','1: Introduction').replace('2Literature','2: Literature').replace('3Preliminaries','3: Preliminaries').replace('4Proposed','4: Proposed').replace('5Experiments','5: Experiments').replace('6Results','6: Results').replace('7Conclusion','7: Conclusion'),self.page))
            if name=='CaptionX' and f.getPlainText().startswith('Table '): self.notify('TableEntry',(0,f.getPlainText(),self.page))
def foot(c,d):
    c.setFont('TimesProject',9); c.drawCentredString(A4[0]/2,1.25*cm,str(d.page))
def P(s): return Paragraph(s,styles['BodyX'])
def H(s): return Paragraph(s,styles['SectionX'])
def B(s): return Paragraph(s,styles['SubX'])
def C(s): return Paragraph(s,styles['CaptionX'])
def chapter(n,title): return [PageBreak(),Paragraph('Chapter '+str(n)+'<br/>'+title,styles['ChapterX'])]
def table(caption,rows,widths=None):
    clean=[[Paragraph(html.escape(str(x)),styles['SmallX']) for x in row] for row in rows]
    t=Table(clean,colWidths=widths,repeatRows=1,hAlign='CENTER')
    t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.4,colors.grey),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e9edf0')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
    return [KeepTogether([C(caption),t]),Spacer(1,8)]
def diagram(number,title,labels,filename):
    w=445; h=104; d=Drawing(w,h)
    n=len(labels); boxw=(w-(n-1)*13)/n
    for i,label in enumerate(labels):
        x=i*(boxw+13); d.add(Rect(x,23,boxw,55,rx=5,ry=5,fillColor=colors.HexColor('#edf2f5'),strokeColor=colors.HexColor('#374e5b')))
        lines=label.split('|')
        for j,line in enumerate(lines): d.add(String(x+boxw/2,56-j*12,line,fontName='TimesProject',fontSize=8.7,textAnchor='middle'))
        if i<n-1:
            x1=x+boxw; d.add(Line(x1+2,50,x1+11,50,strokeColor=colors.black)); d.add(Polygon([x1+11,50,x1+7,52.5,x1+7,47.5],fillColor=colors.black,strokeColor=colors.black))
    mer='flowchart LR\n'+'\n'.join('    N%d["%s"]'%(i,l.replace('|',' ')) for i,l in enumerate(labels))+'\n'+'\n'.join('    N%d --> N%d'%(i,i+1) for i in range(n-1))+'\n'
    (ROOT/'diagrams'/filename).write_text(mer,encoding='utf-8')
    return [d,C('Figure '+number+': '+title)]
def listing(notification):
    t=TableOfContents(); t.levelStyles=[styles['TOCX'],styles['TOCX']]; t._notifyKind=notification; return t
