story += [H('6.1 Model comparison by EER'),P('Table 6.1 reports the recorded same-pair comparison. Lower EER indicates a smaller error rate at the empirical equal-error operating point; AUC closer to one indicates better separation on these sampled scores. The 0.0% result is an observed sample value, not evidence that the true error rate is zero. DenseNet121 ArcFace was selected for subsequent embedding generation and retrieval experiments.')]
comparison=list(csv.DictReader((PROJECT/'outputs/eer_comparison/comparison.csv').open(encoding='utf-8')))
rows=[['Checkpoint','EER (%)','ROC AUC']]
for r in sorted(comparison,key=lambda x:float(x['eer'])):
    rows.append([r['model'].replace('__best','').replace('tune__','').replace('_',' '),f"{100*float(r['eer']):.2f}",f"{float(r['auc']):.6f}"])
story += table('Table 6.1: EER comparison of best checkpoints (1,000 genuine and 1,000 impostor pairs)',rows,[270,70,90])
story += [P('The pairs are not necessarily statistically independent because one image or finger can appear in several pairs. Sampling was uniform over eligible finger classes for genuine pairs and over image pairs for impostors; this mixture influences the measured operating point. The test set includes synthetic alterations. Performance on independent captures, partial latent prints or a different population may differ substantially.'),H('6.2 DenseNet retrieval results')]
story += table('Table 6.2: Exact-position DenseNet retrieval results for 1,000 queries',[['Original rank','Correct / 1,000','Accuracy','Mean cosine'],['2','999','99.9%','0.9425'],['4','997','99.7%','0.8969'],['6','994','99.4%','0.8637']],[110,120,100,100])
