for i,(name,val) in enumerate([('Rank 2',99.9),('Rank 4',99.7),('Rank 6',99.4)]):
    x=55+i*130; height=val*1.05
    d.add(Rect(x,25,70,height,fillColor=colors.HexColor('#778f9c'),strokeColor=colors.HexColor('#374e5b')))
